var t=`1425-pulaka-in-coconut-cream`;var i=`world-1425`;var n=`TV`;var o=`oceania`;var r=4;var s=58;var u={en:`Pulaka in Coconut Cream`,ua:`Пулака в кокосових вершках`};var l={en:`Tuvaluan pulaka is giant swamp taro, traditionally cooked and served with coconut cream. This uses ordinary edible taro as a substitute.`,ua:`Пулака в Тувалу, гігантське болотне таро, яке традиційно готують із кокосовими вершками. Тут використано звичайне харчове таро.`};var c=[{en:`Peel store-bought edible taro, cut into 4–5 cm pieces and rinse. Do not use unidentified or wild taro.`,ua:`Очистіть куплене харчове таро, наріжте шматками 4–5 см і промийте. Не використовуйте невизначене або дикоросле таро.`,t:[`peeling`],m:10,i:[[`taro-root`,950,`g`]]},{en:`Boil taro in ample fresh water 30–40 minutes until fully soft, then drain and discard cooking water.`,ua:`Варіть таро у великій кількості чистої води 30–40 хвилин до повної м’якості, потім злийте воду.`,t:[`boiling`,`draining`],m:40,i:[[`water`,2e3,`ml`]]},{en:`Warm coconut cream over low heat with a pinch of salt, stirring until smooth and steaming.`,ua:`Нагрійте кокосові вершки на слабкому вогні з дрібкою солі, помішуючи до однорідності й появи пари.`,t:[`gentle-simmering`],m:6,i:[[`coconut-cream`,350,`ml`],[`sea-salt`,4,`g`]]},{en:`Spoon coconut cream over hot taro and serve immediately.`,ua:`Полийте гаряче таро кокосовими вершками й негайно подавайте.`,t:[`garnishing`],m:2,i:[]}];var m={slug:t,id:i,country:`TV`,region:o,servings:4,minutes:58,title:u,text:l,steps:c};export{n as country,m as default,i as id,s as minutes,o as region,r as servings,t as slug,c as steps,l as text,u as title};